import{_ as a,C as n,o as i,c as o,E as r,a2 as d}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.6","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.6","type":"implementation-case","domain":"TMPA","version":"I0.6","status":"public-draft","source":"github-main","related":["TMPA Architecture Paper","TMPA Core Specification","FCoP","CodeFlowMu"],"outline":"deep"},"headers":[],"relativePath":"en/publications/implementation-case-i0.6.md","filePath":"en/publications/implementation-case-i0.6.md","lastUpdated":1786085052000}'),s={name:"en/publications/implementation-case-i0.6.md"};function c(l,e,p,h,u,m){const t=n("ArticleCover");return i(),o("div",null,[r(t,{image:"/assets/covers/implementation-case.svg",kicker:"Engineering Case",title:"TMPA Implementation Case",summary:"An S0.5 author-run engineering evidence baseline across the Reference Reader, FCoP, CodeFlowMu, and WP-13.",version:"I0.6",status:"S0.5 engineering evidence draft",languageHref:"/zh/publications/implementation-case-i0.6",languageLabel:"简体中文"}),e[0]||(e[0]=d(`<h1 id="tmpa-implementation-and-case-report" tabindex="-1">TMPA Implementation and Case Report <a class="header-anchor" href="#tmpa-implementation-and-case-report" aria-label="Permalink to &quot;TMPA Implementation and Case Report&quot;">​</a></h1><h2 id="s0-5-reference-reader-fcop-v3-2-5-codeflowmu-local-snapshot-and-wp-13" tabindex="-1">S0.5 Reference Reader, FCoP v3.2.5, CodeFlowMu Local Snapshot, and WP-13 <a class="header-anchor" href="#s0-5-reference-reader-fcop-v3-2-5-codeflowmu-local-snapshot-and-wp-13" aria-label="Permalink to &quot;S0.5 Reference Reader, FCoP v3.2.5, CodeFlowMu Local Snapshot, and WP-13&quot;">​</a></h2><blockquote><p><strong>Document Version:</strong> Draft I0.6<br><strong>Status:</strong> Author-produced implementation and case report<br><strong>Normative Target:</strong> <a href="/joinwell52/en/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a><br><strong>Historical Baseline:</strong> I0.5 preserves the S0.4 corpus and WP-13 publication package<br><strong>Evidence Capture:</strong> 2026-08-07, Asia/Shanghai<br><strong>Evidence Package:</strong> <code>tmpa-i0.6-local-evidence-20260806-v2</code><br><strong>Authority Boundary:</strong> This report is evidentiary and non-normative. Only the Core Specification defines TMPA requirements.</p></blockquote><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>I0.6 is the first Implementation Case revision to evaluate fresh product evidence against TMPA Core S0.5. It combines four deliberately separate tracks: the S0.5 Reference Reader, the FCoP v3.2.5 protocol reference implementation, an isolated byte-for-byte snapshot of a local CodeFlowMu worktree, and the previously published WP-13 multi-agent evidence-gating case. XiaoDian AI remains lineage and candidate field evidence; no fixed XiaoDian S0.5 package was run.</p><p>The S0.5 Reference Reader passes <strong>14/14</strong> author-produced synthetic criteria. Product evidence does not inherit those results. The product-level matrix is <strong>1 PASS, 8 PARTIAL, 3 NOT RUN, and 2 FAIL</strong>: C14 passes; C02 and C07 fail; C01, C03–C06, C09, C10, and C13 are partial; C08, C11, and C12 were not run. FCoP records 1,222 passed, 3 failed, and 2 skipped tests. CodeFlowMu records 8/8 protocol fixtures, 1,420 passed / 1 failed / 1 skipped Runtime tests, 770/770 Shell tests, and successful type checks for Protocol, Runtime, and Shell.</p><p>The evidence therefore supports implementation and author-demonstrated behavior, not complete S0.5 conformance, independent validation, or independent adoption. Failures are retained as evidence. WP-13 demonstrates governance containment of an unverified completion claim; it does not prove that a model ceased to hallucinate.</p><h1 id="_1-scope-and-research-questions" tabindex="-1">1. Scope and Research Questions <a class="header-anchor" href="#_1-scope-and-research-questions" aria-label="Permalink to &quot;1. Scope and Research Questions&quot;">​</a></h1><p>This report asks:</p><ol><li>Can the S0.5 normative interpretation be executed deterministically by the published Reference Reader?</li><li>Which S0.5 criteria have current product-level evidence in FCoP and CodeFlowMu?</li><li>Where do observed product behaviors still diverge from the Core contract?</li><li>What does WP-13 demonstrate about multi-agent evidence gating under uncertain tool results?</li></ol><p>The unit of judgment is a criterion-bound evidence claim, not a product reputation claim. The report uses four maturity labels without collapsing them:</p><table tabindex="0"><thead><tr><th>Level</th><th>Meaning in I0.6</th></tr></thead><tbody><tr><td>Specified</td><td>Defined by TMPA Core S0.5</td></tr><tr><td>Implemented</td><td>A corresponding mechanism exists in code or protocol artifacts</td></tr><tr><td>Demonstrated</td><td>An author-run execution produced inspectable evidence</td></tr><tr><td>Independently Adopted</td><td>A separate organization adopted and validated the mechanism</td></tr></tbody></table><p>No I0.6 claim reaches independently adopted.</p><h1 id="_2-architecture-and-component-boundaries" tabindex="-1">2. Architecture and Component Boundaries <a class="header-anchor" href="#_2-architecture-and-component-boundaries" aria-label="Permalink to &quot;2. Architecture and Component Boundaries&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture</span></span>
<span class="line"><span>       ↓ normative contract</span></span>
<span class="line"><span>TMPA Core S0.5</span></span>
<span class="line"><span>       ↓ reusable protocol profile</span></span>
<span class="line"><span>FCoP protocol</span></span>
<span class="line"><span>       ↓ reference implementation</span></span>
<span class="line"><span>fcop / fcop-mcp</span></span>
<span class="line"><span>       ↓ downstream adoption</span></span>
<span class="line"><span>CodeFlowMu application and WP-13 workflow</span></span></code></pre></div><p>TMPA is the governance architecture. FCoP is a reusable protocol profile, not an application and not a <code>pip install</code> product claim. The <code>fcop</code> and <code>fcop-mcp</code> packages are reference implementations of that protocol. CodeFlowMu is a downstream application that uses FCoP concepts and operations for persistent roles, tasks, reports, reviews, recovery, and audit surfaces. WP-13 is one bounded CodeFlowMu field case. XiaoDian AI belongs to the engineering lineage but was not executed as an S0.5 product input in this run.</p><p>Conceptual layering and historical lineage remain distinct:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONCEPTUAL: TMPA → FCoP → CodeFlowMu / other applications</span></span>
<span class="line"><span>HISTORICAL: XiaoDian practice → early TMPA → FCoP extraction</span></span>
<span class="line"><span>                                   → CodeFlowMu → current TMPA formalization</span></span></code></pre></div><h1 id="_3-evidence-design-and-fixed-sources" tabindex="-1">3. Evidence Design and Fixed Sources <a class="header-anchor" href="#_3-evidence-design-and-fixed-sources" aria-label="Permalink to &quot;3. Evidence Design and Fixed Sources&quot;">​</a></h1><p>The V2 package preserves commands, environments, stdout/stderr logs, structured summaries, a criterion matrix, source inventory, privacy-redaction report, and SHA-256 manifest. V2 corrects a narrative error in V1 without rerunning or altering any raw product log.</p><table tabindex="0"><thead><tr><th>Source</th><th>Fixed identity</th><th>Evidence role</th><th>Boundary</th></tr></thead><tbody><tr><td>TMPA publication</td><td>Commit <code>653e7ba0…</code></td><td>S0.5 schemas, fixtures, and Reference Reader</td><td>Author implementation</td></tr><tr><td>FCoP</td><td>Tag <code>v3.2.5</code>, commit <code>b3dc2343…</code></td><td>Protocol and clean detached reference implementation</td><td>Public fixed source</td></tr><tr><td>CodeFlowMu</td><td>Base <code>c4ebc146…</code>, version <code>0.3.0-alpha</code></td><td>Isolated product/test snapshot</td><td>Dirty local source: 39 modified and 47 untracked files</td></tr><tr><td>WP-13</td><td>Commit <code>609571dd…</code>, V3 ZIP SHA-256 <code>5b5eda30…</code></td><td>Multi-agent fact-check field case</td><td>Author-produced, role-separated QA; not third-party validation</td></tr><tr><td>XiaoDian AI</td><td>No fixed S0.5 package</td><td>Lineage and candidate case</td><td>NOT RUN</td></tr></tbody></table><p>The CodeFlowMu snapshot is byte-for-byte isolated from the working tree for execution, but it is not a stable public release. It can support author-run local evidence only.</p><h1 id="_4-fcop-and-codeflowmu-engineering-mapping" tabindex="-1">4. FCoP and CodeFlowMu Engineering Mapping <a class="header-anchor" href="#_4-fcop-and-codeflowmu-engineering-mapping" aria-label="Permalink to &quot;4. FCoP and CodeFlowMu Engineering Mapping&quot;">​</a></h1><p>FCoP provides project-visible coordination through routed textual objects, lifecycle paths, atomic publication, append-only transitions, explicit roles, independent reports and reviews, issues, alerts, and history. Its project-visible model supports reconstruction outside a transient agent session.</p><p>CodeFlowMu adds application runtime behavior: persistent work identities, PM/DEV/QA/OPS role interfaces, skill and tool invocation, workflow scheduling, review gates, dependency waiting, recovery, approval boundaries, and user-facing operational views. These application mechanisms may implement or demonstrate parts of S0.5, but they do not redefine the FCoP protocol or TMPA Core criteria.</p><p>The principal common gap is a maintained product projection that converts native artifacts into the complete S0.5 governance-object and Reader-result surface. Without that projection, local controls may work while canonical objects, issue codes, three-valued judgments, and deterministic aggregate views remain incomplete.</p><h1 id="_5-executed-test-baseline" tabindex="-1">5. Executed Test Baseline <a class="header-anchor" href="#_5-executed-test-baseline" aria-label="Permalink to &quot;5. Executed Test Baseline&quot;">​</a></h1><p>All primary runs were author-executed. A PASS in the Reference Reader track is never copied into the product track.</p><table tabindex="0"><thead><tr><th>Track</th><th style="text-align:right;">Result</th><th style="text-align:right;">Exit</th><th>Interpretation</th></tr></thead><tbody><tr><td>S0.5 Reference Reader</td><td style="text-align:right;">14 passed</td><td style="text-align:right;">0</td><td>Executable interpretation over synthetic fixtures</td></tr><tr><td>FCoP v3.2.5 full suite</td><td style="text-align:right;">1,222 passed, 3 failed, 2 skipped</td><td style="text-align:right;">1</td><td>Product assertions include three retained failures</td></tr><tr><td>FCoP library CI subset</td><td style="text-align:right;">907 passed, 1 failed</td><td style="text-align:right;">1</td><td><code>parent</code> persistence/readback gap</td></tr><tr><td>FCoP MCP CI subset</td><td style="text-align:right;">78 passed, 2 failed</td><td style="text-align:right;">1</td><td>report lifecycle and tool-surface snapshot gaps</td></tr><tr><td>CodeFlowMu Protocol</td><td style="text-align:right;">8/8</td><td style="text-align:right;">0</td><td>Five valid and three expected-invalid fixtures</td></tr><tr><td>CodeFlowMu Runtime</td><td style="text-align:right;">1,420 passed, 1 failed, 1 skipped</td><td style="text-align:right;">1</td><td>One retained human-prompt contract mismatch</td></tr><tr><td>CodeFlowMu Shell</td><td style="text-align:right;">770/770</td><td style="text-align:right;">0</td><td>Full isolated Shell snapshot</td></tr><tr><td>Protocol / Runtime / Shell type checks</td><td style="text-align:right;">all passed</td><td style="text-align:right;">0</td><td>Static checks only</td></tr><tr><td>WP-13 V3 validation</td><td style="text-align:right;">passed</td><td style="text-align:right;">0</td><td>23/23 internal hashes and structured-data checks</td></tr></tbody></table><p>Two FCoP stdout files were normalized into decodable UTF-8 and contain U+FFFD replacement characters. Counts, exit codes, and identified failure names remain intact, but the package does not claim byte-for-byte preservation of the original process output.</p><h1 id="_6-c01–c14-product-results" tabindex="-1">6. C01–C14 Product Results <a class="header-anchor" href="#_6-c01–c14-product-results" aria-label="Permalink to &quot;6. C01–C14 Product Results&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>S0.5 criterion</th><th style="text-align:right;">Reader</th><th style="text-align:right;">Product</th><th>Product evidence boundary</th></tr></thead><tbody><tr><td>C01</td><td>Schema validation</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Selected positive and negative schema paths ran; the full canonical object surface did not.</td></tr><tr><td>C02</td><td>Primary carrier and immutability</td><td style="text-align:right;">PASS</td><td style="text-align:right;"><strong>FAIL</strong></td><td>FCoP <code>parent</code> was accepted on the write surface but not closed through persistence/readback and published surface snapshots.</td></tr><tr><td>C03</td><td>Duplicate identity</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Duplicate/conflict mechanisms exist; canonical product quarantine output is incomplete.</td></tr><tr><td>C04</td><td>Stream continuity and asynchronous progress</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Ordering and dependency mechanisms ran without a complete canonical partial-order graph.</td></tr><tr><td>C05</td><td>Role authority</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Role gates ran; complete S0.5 authority issue/judgment output did not.</td></tr><tr><td>C06</td><td>Lifecycle legality</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Lifecycle controls ran; the complete required three-valued canonical outputs did not.</td></tr><tr><td>C07</td><td>Separation of duties and human control</td><td style="text-align:right;">PASS</td><td style="text-align:right;"><strong>FAIL</strong></td><td>Human-control structure exists, but one mandatory prompt-contract assertion failed.</td></tr><tr><td>C08</td><td>Integrity tampering</td><td style="text-align:right;">PASS</td><td style="text-align:right;">NOT RUN</td><td>Adjacent hashes do not substitute for the product criterion.</td></tr><tr><td>C09</td><td>Missing reference</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Failure visibility exists; canonical <code>undetermined</code> propagation is incomplete.</td></tr><tr><td>C10</td><td>Prohibited cycle</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Local cycle detection passed; canonical affected-subgraph isolation did not run.</td></tr><tr><td>C11</td><td>Deterministic reconstruction</td><td style="text-align:right;">PASS</td><td style="text-align:right;">NOT RUN</td><td>Only the Reference Reader performed the required permutation-equivalent reconstruction.</td></tr><tr><td>C12</td><td>Conflict preservation</td><td style="text-align:right;">PASS</td><td style="text-align:right;">NOT RUN</td><td>Adjacent conflict mechanisms exist; the exact product criterion did not run.</td></tr><tr><td>C13</td><td>Recovery</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>File-fact recovery is demonstrated; complete fresh-reader reconstruction is not.</td></tr><tr><td>C14</td><td>Terminal-history preservation</td><td style="text-align:right;">PASS</td><td style="text-align:right;"><strong>PASS</strong></td><td>Product tests support retained terminal history and authorization behavior.</td></tr></tbody></table><p>Product aggregate: <strong>1 PASS / 8 PARTIAL / 3 NOT RUN / 2 FAIL</strong>. The aggregate is not conformant.</p><h1 id="_7-retained-failure-analysis" tabindex="-1">7. Retained Failure Analysis <a class="header-anchor" href="#_7-retained-failure-analysis" aria-label="Permalink to &quot;7. Retained Failure Analysis&quot;">​</a></h1><h2 id="_7-1-c02-—-fcop-parent-closure" tabindex="-1">7.1 C02 — FCoP <code>parent</code> closure <a class="header-anchor" href="#_7-1-c02-—-fcop-parent-closure" aria-label="Permalink to &quot;7.1 C02 — FCoP \`parent\` closure&quot;">​</a></h2><p>The FCoP failures are not treated as a failure of the FCoP protocol definition itself. They show a reference-implementation release-consistency gap: the optional <code>parent</code> field appears on the current API/MCP surface, but round-trip persistence/readback and stored public-surface snapshots are not all synchronized. Until the same object survives the complete write–persist–read path and surface snapshots are updated under release control, C02 remains FAIL.</p><h2 id="_7-2-c07-—-human-adjudication-prompt-contract" tabindex="-1">7.2 C07 — human-adjudication prompt contract <a class="header-anchor" href="#_7-2-c07-—-human-adjudication-prompt-contract" aria-label="Permalink to &quot;7.2 C07 — human-adjudication prompt contract&quot;">​</a></h2><p>The CodeFlowMu Runtime test expected either <code>需 ADMIN 人工裁定</code> or <code>需人工裁定</code>. The actual readable output was <code>需 ADMIN/PM 人工裁定</code>. Structured fields remained valid—<code>decision=needs_human</code>, <code>fact_check_verdict=needs_admin</code>, and <code>awaiting_pm_decision=true</code>—and lifecycle did not advance.</p><p>The failure is therefore a wording-contract mismatch, not Chinese encoding damage. The raw mandatory assertion failed, so C07 remains FAIL until the product and test owners decide whether <code>ADMIN/PM</code> is an intended product contract or the test expectation is stale, make the corresponding change, and rerun the complete Runtime acceptance suite.</p><h1 id="_8-wp-13-multi-agent-evidence-gating-case" tabindex="-1">8. WP-13 Multi-Agent Evidence-Gating Case <a class="header-anchor" href="#_8-wp-13-multi-agent-evidence-gating-case" aria-label="Permalink to &quot;8. WP-13 Multi-Agent Evidence-Gating Case&quot;">​</a></h1><p>WP-13 asks whether a multi-agent governance chain can prevent an unverified completion claim from becoming an authoritative delivery fact. A DEV subexecution ended with completion-meaning language while exit status, tests, commit, and formal report were not all confirmed. PM checked persistent facts, withheld release, and did not dispatch QA. After tool recovery, DEV completed the same task, produced commit <code>609571dd…</code> and a formal report, and role-separated QA reran 27 tests, type checking, and diff checks successfully.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>completion-meaning claim</span></span>
<span class="line"><span>        ↓ persistent evidence incomplete</span></span>
<span class="line"><span>PM fact check → hold / do not release / do not dispatch QA</span></span>
<span class="line"><span>        ↓ same-task recovery</span></span>
<span class="line"><span>DEV commit + report</span></span>
<span class="line"><span>        ↓ separate role</span></span>
<span class="line"><span>QA rerun and report</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>candidate evidence for authorized decision</span></span></code></pre></div><p>At the first observation point, “WP-13 is complete” was neither established as <code>valid</code> nor proved <code>invalid</code>; the appropriate S0.5 analytical judgment was <code>undetermined</code>. This is a retrospective TMPA projection. The native application did not emit the complete canonical S0.5 Reader envelope.</p><p>The case demonstrates governance containment, role separation, same-task recovery, and evidence completion. It does not prove elimination of hallucinations, independent validation, terminal approval within the original snapshot, cryptographic provenance, or independently adopted TMPA conformance.</p><p>The V3 package records <code>runtime_bound: false</code>; its snapshot ends while TASK-019/020 are still <code>review / pending</code>. Gate C acceptance occurred later and remains a separate lifecycle fact. “DEV complete,” “QA pass,” “Gate C accept,” “done,” and “archive” must not be collapsed.</p><h1 id="_9-three-valued-governance-interpretation" tabindex="-1">9. Three-Valued Governance Interpretation <a class="header-anchor" href="#_9-three-valued-governance-interpretation" aria-label="Permalink to &quot;9. Three-Valued Governance Interpretation&quot;">​</a></h1><p>TMPA separates semantic judgment from view classification:</p><table tabindex="0"><thead><tr><th>Judgment</th><th>Typical view</th><th>Meaning</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>Required evidence and applicable rules establish the conclusion.</td></tr><tr><td><code>invalid</code></td><td>quarantined / rejected</td><td>A deterministic violation excludes the affected evidence or action.</td></tr><tr><td><code>undetermined</code></td><td>partial / disputed / pending_human</td><td>Required evidence is missing, conflicting, or awaiting authorized human decision.</td></tr></tbody></table><p>FCoP and CodeFlowMu already expose many source facts needed by this model, but I0.6 does not claim that either product emits the complete S0.5 canonical graph, issue set, judgment, and view for every criterion. Reference Reader PASS establishes an executable interpretation; product verdicts describe the current projection and execution gap.</p><h1 id="_10-reproducibility-and-evidence-quality" tabindex="-1">10. Reproducibility and Evidence Quality <a class="header-anchor" href="#_10-reproducibility-and-evidence-quality" aria-label="Permalink to &quot;10. Reproducibility and Evidence Quality&quot;">​</a></h1><p>The V2 archive contains 125 ZIP entries and 122 payload hashes. Its archive CRC, payload SHA-256 manifest, 45 JSON files, relevant JSONL, strict UTF-8 decoding after documented normalization, filename safety, absolute-path scan, and credential scan pass. All V1/V2 raw log files are byte-identical; V2 changes only summaries, matrix language, validation metadata, and the explicit encoding boundary.</p><p>The strongest reproducible statements are:</p><ul><li>the S0.5 Reference Reader produced 14/14 PASS on its fixed synthetic fixtures;</li><li>the listed FCoP and CodeFlowMu test counts and failures are preserved in raw logs;</li><li>WP-13 V3 passed its internal package validation;</li><li>the C01–C14 product matrix follows the declared strict rule that one failed mandatory assertion prevents PASS.</li></ul><p>The package is author-produced local evidence. It is not signed, independently timestamped, independently rerun, or a stable public CodeFlowMu release snapshot.</p><h1 id="_11-limitations" tabindex="-1">11. Limitations <a class="header-anchor" href="#_11-limitations" aria-label="Permalink to &quot;11. Limitations&quot;">​</a></h1><ol><li>FCoP and CodeFlowMu are maintained by project participants; this creates author and implementation bias.</li><li>The CodeFlowMu source worktree was dirty and local-only, despite isolated execution.</li><li>C08, C11, and C12 lack exact product execution.</li><li>C01, C03–C06, C09, C10, and C13 lack complete canonical product output.</li><li>C02 and C07 retain executed failures.</li><li>XiaoDian AI had no fixed S0.5 package and was NOT RUN.</li><li>No evidence establishes representative SME performance, adoption cost, comparison baselines, broad fault recovery, Byzantine resilience, or third-party adoption.</li><li>U+FFFD characters in two normalized FCoP logs limit byte-level forensic claims.</li></ol><h1 id="_12-engineering-roadmap" tabindex="-1">12. Engineering Roadmap <a class="header-anchor" href="#_12-engineering-roadmap" aria-label="Permalink to &quot;12. Engineering Roadmap&quot;">​</a></h1><ol><li>Close FCoP <code>parent</code> persistence/readback and release-surface snapshots, then rerun the full v3.2.5-equivalent suite.</li><li>Adjudicate the CodeFlowMu <code>ADMIN/PM</code> prompt contract, implement the approved product-or-test change, and rerun the complete Runtime suite.</li><li>Publish a retrievable clean CodeFlowMu candidate or reproduction snapshot.</li><li>Implement maintained FCoP and CodeFlowMu S0.5 projection adapters.</li><li>Execute C08, C11, and C12 and complete canonical outputs for all PARTIAL criteria.</li><li>Establish a fixed XiaoDian evidence package before making new S0.5 claims.</li><li>Obtain independent reruns and preserve all deviations.</li></ol><h1 id="_13-engineering-conclusion" tabindex="-1">13. Engineering Conclusion <a class="header-anchor" href="#_13-engineering-conclusion" aria-label="Permalink to &quot;13. Engineering Conclusion&quot;">​</a></h1><p>I0.6 advances the Implementation Case from the historical S0.4 baseline to a fresh S0.5 author-run evidence baseline. The result is intentionally mixed: the Reference Reader passes all 14 synthetic criteria, while product evidence contains one PASS, eight PARTIAL, three NOT RUN, and two FAIL. This is stronger and more informative than a success-only demonstration because it identifies specific implementation and projection gaps without weakening the normative contract.</p><p>FCoP remains the protocol layer; its packages are the reference implementation. CodeFlowMu remains the downstream application. WP-13 supplies a bounded multi-agent governance case showing that persistent evidence and separated roles can contain an unverified completion claim. None of these engineering observations proves the TMPA theory, full product conformance, or independent adoption.</p><h1 id="artifact-availability" tabindex="-1">Artifact Availability <a class="header-anchor" href="#artifact-availability" aria-label="Permalink to &quot;Artifact Availability&quot;">​</a></h1><p>The complete V2 evidence archive is available at <a href="/joinwell52/evidence/tmpa/i0.6/tmpa-i0.6-local-evidence-20260806-v2.zip">tmpa-i0.6-local-evidence-20260806-v2.zip</a>, SHA-256 <code>c55cb41fb90f63216fafe6e5b552f4917e56910d120d3b51486f96eba066c2d0</code>. Reviewable matrix, test-summary, source-inventory, validation, and redaction metadata are stored under <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s0.5/external-runs/20260806-local-evidence-v2" target="_blank" rel="noreferrer"><code>research/conformance/tmpa-core-s0.5/external-runs/20260806-local-evidence-v2</code></a>.</p><p>The historical S0.4 corpus remains at <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s0.4" target="_blank" rel="noreferrer"><code>research/conformance/tmpa-core-s0.4</code></a>. WP-13 V3 remains at <code>/evidence/tmpa/i0.5/</code>. Git history is the publication version history; no separate paper archive has editorial authority.</p><h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>[1] TMPA Project. “TMPA Core Specification S0.5.” GitHub, 2026.</p><p>[2] TMPA Project. “TMPA Architecture Paper A0.7.” GitHub, 2026.</p><p>[3] FCoP Project. “FCoP — File-based Coordination Protocol,” tag v3.2.5, commit <code>b3dc23439c6aaa6a6b3765655b87e5924e0257f9</code>. GitHub, 2026.</p><p>[4] CodeFlowMu Project. Local isolated evidence snapshot based on commit <code>c4ebc146cb8ef0409a4c9eb571a8f2432ade3bd0</code>, version <code>0.3.0-alpha</code>, captured 2026-08-07.</p><p>[5] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3,” commit <code>609571ddb22d1fbb2bfb5e54692c07beeef4cf23</code>, 2026.</p><p>[6] TMPA Project. “I0.6 Local Engineering Evidence V2,” package <code>tmpa-i0.6-local-evidence-20260806-v2</code>, 2026.</p>`,71))])}const b=a(s,[["render",c]]);export{f as __pageData,b as default};
